PREFIX in: <http://data.world/schema/insurance/>

SELECT (xsd:decimal(SUM(?premiumValue)) / COUNT(DISTINCT ?policy) AS ?averagePolicySize)
WHERE {
  SERVICE <mapped> {
    ?pcd a in:PolicyCoverageDetail ;
         in:hasPolicy ?policy ;
         in:hasPremiumAmount ?premium .

    ?premium in:premiumAmount ?premiumValue .
  }
}

PREFIX in: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?claimNumber ?policyNumber ?policyHolderId ?premiumAmount
       (COALESCE(SUM(xsd:decimal(?lossPaymentAmt)), 0) AS ?totalLossPayment)
       (COALESCE(SUM(xsd:decimal(?lossReserveAmt)), 0) AS ?totalLossReserve)
       (COALESCE(SUM(xsd:decimal(?expensePaymentAmt)), 0) AS ?totalExpensePayment)
       (COALESCE(SUM(xsd:decimal(?expenseReserveAmt)), 0) AS ?totalExpenseReserve)
       ((COALESCE(SUM(xsd:decimal(?lossPaymentAmt)), 0) +
         COALESCE(SUM(xsd:decimal(?lossReserveAmt)), 0) +
         COALESCE(SUM(xsd:decimal(?expensePaymentAmt)), 0) +
         COALESCE(SUM(xsd:decimal(?expenseReserveAmt)), 0)) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:against ?pcd .

    ?pcd a in:PolicyCoverageDetail ;
         in:hasPolicy ?policy ;
         in:hasPremiumAmount ?premium .

    ?policy a in:Policy ;
            in:policyNumber ?policyNumber ;
            in:hasPolicyHolder ?policyHolder .

    ?policyHolder a in:PolicyHolder ;
                  in:policyHolderId ?policyHolderId .

    ?premium a in:Premium ;
             in:premiumAmount ?premiumAmount .

    OPTIONAL {
      ?claim in:hasLossPayment ?lp .
      ?lp a in:LossPayment ;
          in:lossPaymentAmount ?lossPaymentAmt .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lr .
      ?lr a in:LossReserve ;
          in:lossReserveAmount ?lossReserveAmt .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?ep .
      ?ep a in:ExpensePayment ;
          in:expensePaymentAmount ?expensePaymentAmt .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?er .
      ?er a in:ExpenseReserve ;
          in:expenseReserveAmount ?expenseReserveAmt .
    }
  }
}
GROUP BY ?claimNumber ?policyNumber ?policyHolderId ?premiumAmount
ORDER BY ?claimNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyHolderId ?policyNumber (SUM(?premiumValue) AS ?totalPremiumAmount)
WHERE {
  SERVICE <mapped> {
    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy ;
              in:hasPremiumAmount ?premium .

    ?policy a in:Policy ;
            in:policyNumber ?policyNumber ;
            in:hasPolicyHolder ?policyHolder .

    ?policyHolder a in:PolicyHolder ;
                  in:policyHolderId ?policyHolderId .

    ?premium a in:Premium ;
             in:premiumAmount ?premiumValue .
  }
}
GROUP BY ?policyHolderId ?policyNumber
ORDER BY ?policyHolderId ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?policyNumber ?policyHolderId ?premiumAmount ?catastropheName ?agentId
       ?lossPaymentAmount ?lossReserveAmount ?expensePaymentAmount ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber .

    OPTIONAL {
      ?claim in:hasLossPayment ?lossPayment .
      ?lossPayment in:lossPaymentAmount ?lossPaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lossReserve .
      ?lossReserve in:lossReserveAmount ?lossReserveAmount .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?expensePayment .
      ?expensePayment in:expensePaymentAmount ?expensePaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?expenseReserve .
      ?expenseReserve in:expenseReserveAmount ?expenseReserveAmount .
    }

    OPTIONAL {
      ?claim in:hasCatastrophe ?catastrophe .
      ?catastrophe in:catastropheName ?catastropheName .
    }

    OPTIONAL {
      ?claim in:against ?pcd .
      ?pcd in:hasPolicy ?policy .
      ?policy in:policyNumber ?policyNumber .

      OPTIONAL {
        ?policy in:hasPolicyHolder ?policyHolder .
        ?policyHolder in:policyHolderId ?policyHolderId .
      }

      OPTIONAL {
        ?pcd in:hasPremiumAmount ?premium .
        ?premium in:premiumAmount ?premiumAmount .
      }

      OPTIONAL {
        ?policy in:soldByAgent ?agent .
        ?agent in:agentId ?agentId .
      }
    }
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?agentId ?policyNumber ?claimNumber ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:policyNumber ?policyNumber ;
            in:soldByAgent ?agent .

    ?agent a in:Agent ;
           in:agentId ?agentId .

    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy .

    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:against ?coverage ;
           in:hasExpenseReserve ?expenseReserve .

    ?expenseReserve a in:ExpenseReserve ;
                    in:expenseReserveAmount ?expenseReserveAmount .
  }
}
ORDER BY ?agentId ?policyNumber ?claimNumber ?expenseReserveAmount
